<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vacancy Match</title>
<style>body{margin:0;background:#f6f7f9;color:#17202a;font:15px system-ui,sans-serif}.wrap{max-width:1050px;margin:0 auto;padding:42px 22px}.head{display:flex;justify-content:space-between;align-items:end;margin-bottom:28px}.eyebrow{color:#6b5cff;font-weight:700;letter-spacing:.08em;text-transform:uppercase;font-size:12px}.sub{color:#687385}.filters,.card{background:white;border:1px solid #e4e7ec;border-radius:14px;padding:18px;box-shadow:0 5px 18px #202b3d08}.filters{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px}.filters input,.filters select,.filters button{border:1px solid #d8dde6;border-radius:8px;padding:9px 11px;background:white}.filters button{background:#17202a;color:#fff}.card{margin:14px 0}.cardtop{display:flex;justify-content:space-between;gap:20px}.title{font-size:20px;font-weight:750}.company{color:#687385;margin-top:4px}.score{color:#178653;background:#e9f8ef;padding:7px 10px;border-radius:9px;font-weight:750;white-space:nowrap}.meta{display:flex;gap:8px;flex-wrap:wrap;color:#536071;margin:16px 0}.pill{background:#f0f2f5;padding:5px 9px;border-radius:99px}.skills{display:flex;gap:18px;flex-wrap:wrap}.skills strong{display:block;font-size:12px;color:#687385;margin-bottom:5px}.skills span{margin-right:8px}.matched{color:#178653}.missing{color:#be5c00}.actions{display:flex;justify-content:space-between;margin-top:18px;align-items:center}.actions a{color:#5b4cf0;text-decoration:none;font-weight:650}.actions select{padding:7px;border:1px solid #d8dde6;border-radius:7px}.pager{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-top:24px;padding:16px 18px;background:#fff;border:1px solid #e4e7ec;border-radius:14px}.pager-summary{color:#687385;font-size:14px}.pager-links{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.pager-button,.pager-number{display:inline-flex;align-items:center;justify-content:center;min-height:36px;padding:0 11px;border:1px solid #d8dde6;border-radius:8px;background:#fff;color:#344054;text-decoration:none}.pager-number{min-width:36px;padding:0}.pager-button:hover,.pager-number:hover{border-color:#6b5cff;color:#5b4cf0}.pager-number.active{border-color:#6b5cff;background:#6b5cff;color:#fff}.pager-button.disabled{color:#98a2b3;background:#f7f8fa}.pager-dots{padding:0 3px;color:#98a2b3}@media(max-width:700px){.head,.pager{align-items:flex-start;flex-direction:column}.pager-links{width:100%}.pager-summary{order:2}.pager-number,.pager-dots{display:none}.pager-button{flex:1}.cardtop{align-items:flex-start}}</style></head>
<body><main class="wrap"><div class="head"><div><div class="eyebrow">Job Vacancy Matcher</div><h1>Recommended roles</h1><div class="sub">Ranked against your candidate profile.</div></div><div class="sub"><a href="{{ route('profile.edit') }}" style="color:#5b4cf0;margin-right:14px">Edit profile</a>{{ $matches->total() }} matches</div></div>
<form class="filters" method="get"><input name="min_score" type="number" min="0" max="100" placeholder="Min score" value="{{ request('min_score') }}"><select name="status"><option value="">Any status</option>@foreach(['new','saved','interested','applied','ignored'] as $status)<option value="{{ $status }}" @selected(request('status')===$status)>{{ ucfirst($status) }}</option>@endforeach</select><select name="work_type"><option value="">Any work type</option>@foreach(['remote','hybrid','onsite'] as $type)<option value="{{ $type }}" @selected(request('work_type')===$type)>{{ ucfirst($type) }}</option>@endforeach</select><input name="location" placeholder="Location" value="{{ request('location') }}"><button>Filter</button></form>
@forelse($matches as $match)<article class="card"><div class="cardtop"><div><div class="title">{{ $match->job->title }}</div><div class="company">{{ $match->job->company_name }} · {{ $match->job->source->name }}</div></div><div class="score">{{ number_format($match->total_score, 0) }}% match</div></div><div class="meta"><span class="pill">{{ ucfirst($match->job->work_type) }}</span><span class="pill">{{ $match->job->location }}</span><span class="pill">{{ ucfirst($match->job->job_level) }}</span>@if($match->job->experience_min !== null)<span class="pill">{{ $match->job->experience_min }}–{{ $match->job->experience_max }} yrs</span>@endif</div><div class="skills"><div><strong>Matched skills</strong><span class="matched">✓ {{ implode(' · ', $match->matched_skills ?? []) ?: 'None yet' }}</span></div><div><strong>Missing skills</strong><span class="missing">{{ implode(' · ', $match->missing_skills ?? []) ?: 'None' }}</span></div></div><div class="actions"><a href="{{ $match->job->url }}" target="_blank" rel="noopener">View vacancy ↗</a><form method="post" action="{{ route('matches.status',$match) }}">@csrf @method('PATCH')<select name="status" onchange="this.form.submit()">@foreach(['new','saved','interested','applied','ignored'] as $status)<option value="{{ $status }}" @selected($match->status->value===$status)>{{ ucfirst($status) }}</option>@endforeach</select></form></div></article>@empty<div class="card"><h2>No matches yet</h2><p class="sub">Run <code>php artisan jobs:fetch</code> to fetch live vacancies.</p></div>@endforelse@include('jobs.pagination', ['paginator' => $matches])</main></body></html>
